<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Update;

use RuntimeException;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentity;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class UserFederatedIdentityUpdateCheck
{
    public function __construct(public readonly UserFederatedIdentityUpdateParams $input, public readonly UserFederatedIdentity $current)
    {
    }
    public function reject(RuntimeException|ConstraintFail $fail): void
    {
        if ($fail instanceof ConstraintFail) {
            throw ConstraintException::ofFail($fail);
        } else {
            throw $fail;
        }
    }
}
